UPDATE public.actions a SET macroregion_id = v.macro FROM (VALUES ('Pinhão','centro_sul'),('Francisco Beltrão','sudoeste'),('Andirá','norte_pioneiro'),('Siqueira Campos','norte_pioneiro'),('Dois Vizinhos','sudoeste'),('Califórnia','norte_central'),('Renascença','sudoeste'),('Apucarana','norte_central'),('Pato Branco','sudoeste'),('Altônia','noroeste'),('Umuarama','noroeste'),('Planaltina do Paraná','noroeste'),('Virmond','centro_sul'),('Guarapuava','centro_sul'),('Três Barras do Paraná','oeste'),('Irati','centro_sul'),('Cantagalo','centro_sul'),('Campo Largo','rmc'),('Catanduvas','oeste'),('Curitiba','curitiba'),('Santo Antônio da Platina','norte_pioneiro'),('Cambira','norte_central'),('Rio Negro','rmc'),('Marmeleiro','sudoeste'),('Faxinal','norte_central'),('Quedas do Iguaçu','centro_sul')) AS v(city, macro) WHERE a.municipality = v.city AND a.macroregion_id IS DISTINCT FROM v.macro;